-- Westfall: creature abilities
-- Most of the zone's creatures either had no AI or ran classic rows. Westfall is the Cataclysm revamp, so port their abilities from
-- the Cataclysm data, and from the classic data where Cataclysm has none (Young Fleshripper, Brainwashed Noble), keeping the
-- scripts already in place. The Sentinel Hill and Westfall Brigade guards, which no reference scripts, cast their sniffed
-- spells (creature_template spell1-8).

SET @ENTRIES := '114,117,123,124,127,154,157,199,391,449,452,453,456,462,487,488,489,490,500,501,506,513,515,517,519,573,589,594,596,624,625,830,831,833,834,869,870,874,876,1065,1109,1216,1424,42342,42357,42381,42653,42669,42677,54373';

UPDATE `creature_template` SET `AIName` = 'SmartAI' WHERE FIND_IN_SET(`entry`, @ENTRIES);
DELETE FROM `smart_scripts` WHERE `source_type` = 0 AND FIND_IN_SET(`entryorguid`, @ENTRIES);

-- Creatures without reference data: their sniffed creature_template spell1-8
SET @ENTRIES := '42407,51915';

UPDATE `creature_template` SET `AIName` = 'SmartAI' WHERE FIND_IN_SET(`entry`, @ENTRIES);
DELETE FROM `smart_scripts` WHERE `source_type` = 0 AND FIND_IN_SET(`entryorguid`, @ENTRIES);
